/**
 * Per-activity split / running-dynamics data generated by
 * `run_page/gen_splits.py` into `public/splits/{run_id}.json`.
 * Everything is optional: older runs, GPX/TCX imports or devices without
 * running dynamics simply have no file or null fields.
 */

type N = number | null;

export interface SplitRow {
  index: number;
  distance: N;
  time: N;
  pace: N; // seconds per km
  speed: N; // m/s
  hr_avg: N;
  hr_max: N;
  cadence_avg: N; // steps per minute
  cadence_max: N;
  stride_length: N; // m
  power_avg: N;
  power_max: N;
  normalized_power?: N;
  elev_gain: N;
  elev_loss: N;
  vertical_oscillation: N; // cm
  ground_contact_time: N; // ms
  gct_balance: N; // left %
  vertical_ratio: N; // %
  temperature: N;
  respiration_rate?: N;
  calories?: N;
  intensity?: string | null;
  trigger?: string | null;
  partial?: boolean;
}

export interface RunSummary extends Omit<SplitRow, 'index'> {
  elapsed_time: N;
  moving_time: N;
  best_pace: N;
  aerobic_te: N;
  anaerobic_te: N;
  training_load: N;
  training_stress_score: N;
  intensity_factor: N;
  vo2max: N;
  temperature_min: N;
  temperature_max: N;
  steps: N;
  rpe: N;
  feel: N;
}

export interface ZoneInfo {
  seconds: number[];
  high_boundary: (number | null)[] | null;
  calc_type?: string | null;
  max_hr?: N;
  resting_hr?: N;
  threshold_hr?: N;
  ftp?: N;
}

export interface RunChart {
  d: number[]; // km
  t?: number[]; // seconds from activity start (timer time)
  pace?: N[];
  hr?: N[];
  cad?: N[];
  power?: N[];
  alt?: N[];
  gct?: N[];
  vo?: N[];
  vr?: N[]; // vertical ratio %
  temp?: N[];
}

export interface RunSplits {
  version: number;
  run_id: number;
  sport: string;
  sub_sport: string | null;
  device: string | null;
  summary: RunSummary;
  zones: { hr?: ZoneInfo; power?: ZoneInfo } | null;
  splits: SplitRow[];
  laps: SplitRow[];
  chart: RunChart | null;
}

const BASE = `${(import.meta.env.BASE_URL || '/').replace(/\/?$/, '/')}splits/`;

let indexPromise: Promise<Set<number>> | null = null;
const filePromises = new Map<number, Promise<RunSplits | null>>();

async function fetchJson(url: string): Promise<unknown> {
  const res = await fetch(url);
  if (!res.ok) return null;
  // Dev servers answer unknown paths with index.html; treat that as missing.
  const type = res.headers.get('content-type') || '';
  if (type.includes('text/html')) return null;
  return res.json();
}

/** Ids that have a splits file. Never rejects. */
export function loadSplitsIndex(): Promise<Set<number>> {
  indexPromise ??= fetchJson(`${BASE}index.json`)
    .then((ids) => new Set(Array.isArray(ids) ? ids.map((x) => Number(x)) : []))
    .catch(() => new Set<number>());
  return indexPromise;
}

/** Splits for one run, or null when not generated. Never rejects. */
export function loadSplits(runId: number): Promise<RunSplits | null> {
  let p = filePromises.get(runId);
  if (!p) {
    p = loadSplitsIndex()
      .then((ids) =>
        ids.has(runId) ? fetchJson(`${BASE}${runId}.json`) : null
      )
      .then((d) => (d && typeof d === 'object' ? (d as RunSplits) : null))
      .catch(() => null);
    filePromises.set(runId, p);
  }
  return p;
}

/** "4'05\"" from seconds per km. */
export function formatPaceSeconds(sec: N | undefined): string {
  if (sec == null || !Number.isFinite(sec) || sec <= 0 || sec > 3600)
    return '--';
  const s = Math.round(sec);
  return `${Math.floor(s / 60)}'${String(s % 60).padStart(2, '0')}"`;
}

/** "1:02:03" / "42:10" from seconds. */
export function formatClock(sec: N | undefined): string {
  if (sec == null || !Number.isFinite(sec)) return '--';
  const s = Math.round(sec);
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const r = String(s % 60).padStart(2, '0');
  return h ? `${h}:${String(m).padStart(2, '0')}:${r}` : `${m}:${r}`;
}
